panda_query_payload.query_template:
PREFIX saref: <https://saref.etsi.org/core/>
PREFIX : <https://rsp.js/>
REGISTER RStream <output_{benchmark_run_id}> AS
SELECT ?s ?spo2Value
FROM NAMED WINDOW :w1 ON STREAM <http://localhost:3000/alice/spo2/> [RANGE {query_window_ms} STEP {query_window_ms}]
WHERE {
  WINDOW :w1 {
    ?s saref:hasValue ?spo2Value .
  }
}

panda_query_payload.rules:
@prefix saref: <https://saref.etsi.org/core/> .
@prefix math: <http://www.w3.org/2000/10/swap/math#> .
@prefix ex: <http://example.org/> .

{ ?s saref:hasValue ?spo2Value . ?spo2Value math:lessThan 90. } => { ?s ex:alert "SPO2_LOW" }.
